create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum('admin','editor','reader'); exception when duplicate_object then null; end $$;
do $$ begin create type public.document_provider as enum('r2','demo'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role public.app_role not null default 'reader',status text not null default 'active' check(status in('active','suspended')),created_at timestamptz default now());
create table if not exists public.collections(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text default '');
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),title text not null,authors text[] default '{}',publication_year integer,category text default 'General',description text default '',collection_id uuid references public.collections(id),provider public.document_provider not null default 'r2',r2_key text,demo_path text,mime_type text default 'application/pdf',size_bytes bigint default 0,page_count integer,is_demo boolean default false,is_published boolean default true,created_at timestamptz default now(),constraint r2_key_required check(provider<>'r2' or r2_key is not null));
create table if not exists public.document_grants(document_id uuid references public.documents(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,primary key(document_id,user_id));
create table if not exists public.reading_events(id bigint generated always as identity primary key,document_id uuid references public.documents(id),user_id uuid references public.profiles(id),event_type text check(event_type in('opened','downloaded')),created_at timestamptz default now());
create or replace function public.current_app_role() returns public.app_role language sql stable security definer set search_path=public set row_security=off as $$ select role from public.profiles where id=auth.uid() and status='active' limit 1 $$;
create or replace function public.is_active_user() returns boolean language sql stable security definer set search_path=public set row_security=off as $$ select exists(select 1 from public.profiles where id=auth.uid() and status='active') $$;
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.new_profile();
alter table public.profiles enable row level security; alter table public.collections enable row level security; alter table public.documents enable row level security; alter table public.document_grants enable row level security; alter table public.reading_events enable row level security;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.current_app_role()='admin');
create policy profile_self_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and role=public.current_app_role());
create policy collection_read on public.collections for select to authenticated using(public.is_active_user());
create policy collection_edit on public.collections for all to authenticated using(public.current_app_role() in('admin','editor')) with check(public.current_app_role() in('admin','editor'));
create policy document_read on public.documents for select to authenticated using(is_published and public.is_active_user() and (public.current_app_role()='admin' or exists(select 1 from public.document_grants g where g.document_id=id and g.user_id=auth.uid()) or not exists(select 1 from public.document_grants g where g.document_id=id)));
create policy document_edit on public.documents for all to authenticated using(public.current_app_role() in('admin','editor')) with check(public.current_app_role() in('admin','editor'));
create policy grants_read on public.document_grants for select to authenticated using(user_id=auth.uid() or public.current_app_role()='admin');
create policy grants_admin on public.document_grants for all to authenticated using(public.current_app_role()='admin') with check(public.current_app_role()='admin');
create policy events_read on public.reading_events for select to authenticated using(user_id=auth.uid() or public.current_app_role()='admin');
create policy events_insert on public.reading_events for insert to authenticated with check(user_id=auth.uid() and public.is_active_user());
revoke all on public.profiles,public.collections,public.documents,public.document_grants,public.reading_events from anon;
grant select,update on public.profiles to authenticated; grant select,insert,update,delete on public.collections,public.documents,public.document_grants to authenticated; grant select,insert on public.reading_events to authenticated; grant execute on function public.current_app_role() to authenticated; grant execute on function public.is_active_user() to authenticated;
insert into public.collections(name,slug) values('Geografia imaginaria','geografia-imaginaria'),('Naturaleza','naturaleza'),('Musica','musica') on conflict(slug) do nothing;
insert into public.documents(title,authors,publication_year,category,collection_id,provider,demo_path,size_bytes,page_count,is_demo) select 'Atlas del Archipielago Luminario',array['Elena Mar de Papel'],2026,'Geografia imaginaria',id,'demo','/demo/pdfs/atlas-luminario.pdf',4000,2,true from public.collections where slug='geografia-imaginaria' and not exists(select 1 from public.documents where title='Atlas del Archipielago Luminario');
insert into public.documents(title,authors,publication_year,category,collection_id,provider,demo_path,size_bytes,page_count,is_demo) select 'Herbario de Arrecife Azul',array['Tomas del Invernadero'],2026,'Naturaleza',id,'demo','/demo/pdfs/herbario-arrecife-azul.pdf',4000,2,true from public.collections where slug='naturaleza' and not exists(select 1 from public.documents where title='Herbario de Arrecife Azul');
insert into public.documents(title,authors,publication_year,category,collection_id,provider,demo_path,size_bytes,page_count,is_demo) select 'Cuaderno musical de Ciudad Resonante',array['Mara Afinacion'],2026,'Musica',id,'demo','/demo/pdfs/cuaderno-musica-ciudad.pdf',4000,2,true from public.collections where slug='musica' and not exists(select 1 from public.documents where title='Cuaderno musical de Ciudad Resonante');
